/* AP Statistics Unit 3: Collecting Data, original scenarios for the requested 2020 nine-unit CED, topics 3.1–3.7.
   The learning-unit index is retained for saved progress; Fall 2026 investigative-question coverage is added below.
   All study settings and numerical data are fictional. Teaching and Try-it scenarios are reserved from the pool.
   PixelLab setting illustrations are requested in ART_REQUESTS.md; the art primitive supplies labelled fallbacks. */
const board=(title,lines)=>({t:'board',title,lines});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const evidence=prompt=>{const lines=[];let line='';for(const word of prompt.split(' ')){if((line+' '+word).length>54){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return board('Fictional study: given information',lines);};
const art=(title,src,label)=>({t:'art',title,items:[{src:`stats/${src}.png`,x:320,y:224,h:158,label}]});
/* Boxes and directed segments use one coordinate scale; each arrow runs from a box edge to the next box edge. */
const flow=(blocked=false)=>{const pts={},polys=[],segs=[],notes=[];let n=0;const box=(x,y,w,h,text,col)=>{const keys=['A','B','C','D'].map(k=>k+(n++));[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].forEach((v,i)=>pts[keys[i]]=v);polys.push({v:keys.join(''),col,label:text});};const arrow=(a,b,col)=>{const u='P'+n++,v='P'+n++;pts[u]=a;pts[v]=b;segs.push({v:u+v,arrows:1,col});};
 if(blocked){for(const [y,label,col] of [[5,'Sunny',0],[0,'Shady',2]]){box(0,y,5,2,label,col);box(11,y,7,2,'Mulch / none',col);box(23,y,5,2,'Compare',col);arrow([5,y+1],[11,y+1],col);arrow([18,y+1],[23,y+1],col);notes.push({at:[8,y+2.3],text:'Randomize'},{at:[14.5,y-0.7],text:'within block'});}notes.push({at:[14,9],text:'Block by light first; compare treatments within blocks'});}
 else{box(0,2.5,5,2,'Plots',0);box(11,5,6,2,'Mulch',1);box(11,0,6,2,'No mulch',2);box(23,2.5,5,2,'Compare',3);arrow([5,3.5],[11,6],0);arrow([5,3.5],[11,1],0);arrow([17,6],[23,3.5],1);arrow([17,1],[23,3.5],2);notes.push({at:[8,8.5],text:'Random assignment'},{at:[14,3.5],text:'Treatments'},{at:[25.5,1.2],text:'Mean yield'});}
 return {t:'figure',title:blocked?'Fictional garden: randomized blocks':'Fictional garden: a randomized experiment',view:[-1,29,-2,10],pts,hide:Object.keys(pts).join(''),dots:'',polys,segs,notes};};
/* Equal-area cells are individuals; rows are strata on the left, columns are clusters on the right.
   Selected cells are shaded. This is a schematic population, not a spatial measurement or a data plot. */
const samples=()=>{const pts={},polys=[],notes=[];let n=0;for(const [offset,cluster] of [[0,false],[16,true]])for(let row=0;row<3;row++)for(let col=0;col<6;col++){const x=offset+col*1.8,y=row*1.8,keys=['A','B','C','D'].map(k=>k+n++);[[x,y],[x+1.5,y],[x+1.5,y+1.5],[x,y+1.5]].forEach((p,i)=>pts[keys[i]]=p);const selected=cluster?col===1||col===4:col===row||col===row+3;polys.push({v:keys.join(''),col:cluster?1:row,fill:selected});if(!cluster&&col===0)notes.push({at:[-1.3,y+0.75],text:String.fromCharCode(65+row)});}
 notes.push({at:[5.3,7],text:'Strata: sample from EVERY row'},{at:[21.3,7],text:'Clusters: take WHOLE columns'},{at:[13,-1.2],text:'Shading = selected individuals; all cells = population'});return {t:'figure',title:'Fictional populations: strata versus clusters',view:[-3,29,-2,8],pts,hide:Object.keys(pts).join(''),dots:'',polys,notes};};
const TRY=['A fictional archive labels folders 01 through 47. Read two-digit groups 52, 16, 16, 08, 00, 39 from left to right, skipping repeats and labels outside the range. What is the third selected folder number?',
 'A fictional candle study pairs candles by initial mass, then randomly assigns one candle in each pair to each wick. Which design is used?',
 'A fictional theater randomly samples ticket holders and records their self-chosen seating section and satisfaction. Which scope of inference is justified?'];
const trial=(i,right,wrong,k,hint,pic)=>{const c=choose(right,wrong,k);return {prompt:`Try it: ${TRY[i]} ${c.text}. Answer A, B or C.`,answer:c.letter,options:['A','B','C'],hint,pic};};
export default {
id:'math-h-ap-stats-collecting-data',subject:'math',level:5,grade:9,standard:'AP Statistics Course and Exam Description: original 2020 topics 3.1–3.7, with Fall 2026 investigative questions (1.1 and 1.10); current exam mapping is on the course page',title:'Collecting data',
goal:'Plan sampling and experiments, diagnose bias and confounding, implement random selection and assignment, and justify the scope of inference from a study design.',points:20,
skills:{investigative:'Formulating investigative questions',truth:'Do the data tell the truth?',planning:'Planning a study',sampling:'Random sampling and data collection',bias:'Potential problems with sampling',experiment:'Experimental design vocabulary and principles',design:'Selecting an experimental design',inference:'Inference and experiments'},
outline:[['2026 1.1 / 1.10','Formulating a Statistical Investigation',['investigative']],['3.1','Introducing Statistics: Do the Data We Collected Tell the Truth?',['truth']],['3.2','Introduction to Planning a Study',['planning']],['3.3','Random Sampling and Data Collection',['sampling']],['3.4','Potential Problems with Sampling',['bias']],['3.5','Introduction to Experimental Design',['experiment']],['3.6','Selecting an Experimental Design',['design']],['3.7','Inference and Experiments',['inference']]],
steps:[
 {skill:'truth',say:'Before trusting a claim, ask who supplied the data, how they were selected, and what was measured. A fictional orchard polls only its loyal customers about fruit quality; a large response count cannot repair that selection bias. Random samples still vary by chance, so disagreement between samples alone does not prove a faulty study.',eq:'claim → population → collection method → limits',pic:board('Audit a fictional orchard claim',['Claim: everyone likes the fruit','Data: only loyal customers answered','Missing: other potential customers','Large sample ≠ representative sample'])},
 {skill:'planning',say:'A population is the entire group a question concerns, a sample is the subset studied, and a census attempts to measure every member. A fictional museum wants opinions from all visitors but surveys a sample leaving the exhibit; define the population before choosing whom to ask. A census can still have nonresponse or inaccurate answers.',eq:'all museum visitors = population; surveyed visitors = sample',pic:art('Fictional museum: plan a visitor survey','survey-clipboard','Define the visitors of interest before selecting a sample')},
 {skill:'planning',say:'An observational study records conditions without imposing treatments; an experiment deliberately assigns treatments to experimental units. In a fictional pond study, recording existing shade is observational, while assigning shade covers is experimental. Random selection supports population generalization; random assignment supports cause-and-effect conclusions when the experiment provides convincing evidence.',eq:'observe existing shade ≠ assign shade covers',pic:board('Fictional pond study: who decides?',['Existing shade → observe an association','Assigned cover → impose a treatment','Random selection → population inference','Random assignment → causal evidence'])},
 {skill:'sampling',say:'A simple random sample gives every possible sample of the chosen size the same chance, not merely every individual the same chance. For fictional labels 01 through 64, read random two-digit groups 72, 09, 09, 43, 00, 61: reject out-of-range labels and repeats to select 09, 43 and 61. A generator can instead choose uniformly from unused labels until the required size is reached.',eq:'72 ×; 09 ✓; 09 ×; 43 ✓; 00 ×; 61 ✓',pic:board('Fictional SRS: select distinct valid labels',['Population labels: 01 through 64','Random groups: 72, 09, 09, 43, 00, 61','Keep: 09, 43, 61','Every size-three subset has equal chance'])},
 {skill:'sampling',say:'Stratified random sampling takes a random sample from every stratum; form strata using a characteristic related to the response, with similar individuals within each stratum. Cluster sampling randomly selects whole groups and measures everyone in those selected groups, ideally using groups that each resemble the population, often to reduce travel or cost. In the fictional grids, shaded cells come from every row on the left but only selected whole columns on the right.',eq:'stratified: some from every group; cluster: all from selected groups',pic:samples()},
 {skill:'sampling',say:'A systematic random sample starts at a randomly chosen position and then selects every kth individual on a list. In a fictional queue of 90 people, interval 9 with random start 4 selects 4, 13, 22 and so on; a repeating list pattern matching the interval can produce an unrepresentative sample. Describe the random start and stopping rule, not just “choose randomly.”',eq:'4 → 13 → 22 → … → 85',pic:board('Fictional queue: systematic sampling',['Choose start uniformly from 1 through 9','Start 4; add 9 each time','4, 13, 22, …, 85','Check the list for repeating patterns']),check:{prompt:`Try it: ${TRY[0]}`,answer:39,options:[39,8,16],hint:'Only the first occurrence of a valid label counts toward the sample.',pic:board('Fictional archive: read left to right',['Valid labels: 01 through 47','52, 16, 16, 08, 00, 39','Skip repeats and out-of-range labels'])}},
 {skill:'bias',say:'Undercoverage leaves part of the population out of the sampling frame; nonresponse occurs when selected people do not supply data. A fictional town using only a landline directory undercovers households without landlines, while unanswered calls are nonresponse. Explain how the missing group might differ in the response; increasing sample size alone does not remove systematic bias.',eq:'absent from the frame ≠ selected but not responding',pic:board('Fictional town phone survey',['No landline → missing from frame','Selected but no reply → nonresponse','Could missing people answer differently?','More calls cannot repair an incomplete frame'])},
 {skill:'bias',say:'Response bias arises from inaccurate answers, including leading wording or pressure from an interviewer. A fictional gym asking “How wonderful is our service?” risks response bias; surveying the easiest patrons is convenience sampling, while an open invitation lets volunteers select themselves. Use neutral wording and a probability sample, and do not guess the direction of bias without context.',eq:'wording → response bias; self-selection → voluntary response',pic:board('Fictional gym: diagnose the mechanism',['Leading wording → distorted answers','Nearest patrons → convenience sample','Open review link → voluntary response','Neutral question + random selection'])},
 {skill:'experiment',say:'In a fictional garden, each plot receiving an assigned condition is an experimental unit, and harvested mass is the response variable. Fertilizer type and watering schedule are factors; their settings are levels, and a treatment is a specific combination of levels. With two fertilizer types and three schedules, a full factorial experiment has six treatments, not five.',eq:'2 fertilizer levels × 3 watering levels = 6 treatments',pic:art('Fictional garden: what receives a treatment?','garden-plot-experiment','Unit: plot • Factors: fertilizer and water • Response: yield')},
 {skill:'experiment',say:'A sound experiment compares treatments, randomly assigns experimental units, controls other conditions, and uses replication through multiple independent units per treatment. In the fictional mulch trial, keep water and soil handling alike, randomize plots to mulch or no mulch, and compare mean yields. Random assignment tends to balance other variables but does not guarantee identical groups.',eq:'comparison + random assignment + control + replication',pic:flow()},
 {skill:'experiment',say:'Confounding occurs when treatment effects cannot be separated from another variable, as when all mulched plots also get more water. In human experiments, a placebo mimics a treatment without its active ingredient, while blinding keeps treatment knowledge from influencing responses or evaluations. Double-blind means both subjects and those interacting with or evaluating them do not know assignments; neither device replaces randomization.',eq:'mulch + extra water together → effects cannot be separated',pic:board('Control alternative explanations',['Same water → isolate the mulch comparison','Placebo → account for treatment expectations','Blind subjects → reduce expectation effects','Blind evaluators → reduce assessment bias'])},
 {skill:'design',say:'A completely randomized design assigns all available units to treatments using chance alone. If garden light strongly predicts yield, first block plots into sunny and shady groups, then randomly assign both treatments within each block. Blocking accounts for known response variation; giving every sunny plot one treatment would confound light with treatment.',eq:'block by light → randomize within each block → compare',pic:flow(true),check:trial(1,'matched pairs',['cluster sampling','completely randomized with no pairing'],1,'The units are paired before random assignment within each pair.',board('Fictional candle trial',['Pair candles by initial mass','Randomly assign wicks within each pair','Identify the experimental design']))},
 {skill:'design',say:'Matched pairs is a randomized block design with pairs of similar units or each unit receiving both treatments. In a fictional shoe trial, each runner tests both soles in randomized order and the analysis uses each runner’s difference in comfort scores. Randomizing order helps with fatigue and practice effects; allow a washout period when a treatment could carry over.',eq:'within-runner difference = sole A score - sole B score',pic:board('Fictional shoe trial: matched pairs',['Each runner tries both soles','Randomize order: A then B or B then A','Hold testing conditions alike','Analyze differences within runners'])},
 {skill:'inference',say:'A difference is statistically significant when a result at least as extreme would be unlikely from random assignment alone if the treatments had no effect. In a fictional randomized seed trial, only 12 of 800 no-effect shuffles gave a difference at least as extreme, an estimated probability of 0.015. This supports a treatment effect at a prechosen 0.05 threshold, but significance does not measure practical importance or the probability that no effect is true.',eq:'12/800 = 0.015 < 0.05',pic:board('Fictional seed trial: chance comparison',['Assume treatments have no effect','Shuffle assignments; compare differences','At least as extreme: 12 of 800','Estimated probability: 0.015'])},
 {skill:'inference',say:'Check random selection and random assignment separately to determine scope of inference. With both, a well-conducted experiment can support causal conclusions for the sampled population; with random selection alone, it can generalize an association but not establish cause. Assignment alone supports causal inference for the experimental units, with broader generalization limited; neither permits either leap by design alone.',eq:'selection → population; assignment → cause',pic:board('Scope of inference: two separate questions',['Selection + assignment → both possible','Selection only → population association','Assignment only → cause for study units','Neither → describe the observed group'])},
 {skill:'inference',say:'A fictional sleep trial recruits volunteers and randomly assigns quiet or ordinary rooms, finding a statistically significant difference in sleep quality. Assignment supports a causal effect for these volunteers under the study conditions, but volunteer recruitment does not justify generalizing to all adults. If a study finds no significant difference, report insufficient evidence rather than claiming the treatments are identical.',eq:'volunteers + random assignment → limited causal scope',pic:board('Fictional sleep trial: justify the conclusion',['Volunteers → no random population sample','Random assignment → treatment comparison','Significant result → evidence of an effect','Generalization to all adults is not justified']),check:trial(2,'generalize an association to ticket holders; no causal claim',['prove seating causes satisfaction for everyone','prove no association exists'],2,'Look for random selection and ask whether seating was assigned.',board('Fictional theater survey',['Random sample of ticket holders','Seating section is self-chosen','Satisfaction is recorded']))},
{"skill":"investigative","say":"Define a question before collecting and analyzing its data. A fictional repair depot wants a plausible range for the mean completion time of all repairs finished this month. Record completion time in hours for a suitable sample of those repairs. The question identifies a variable, a population and an estimation goal. One repair time alone cannot describe the population mean.","eq":"Repair → hours; all repairs this month → population; range for mean → estimation","pic":{"t":"board","title":"Fictional repair depot: define the investigation","lines":["Variable: completion time in hours","Population: all repairs finished this month","Goal: a plausible range for the population mean","Select data that address this question"]}},{"skill":"investigative","say":"A fictional packing trial randomly assigns participating packers to a new layout or the usual layout and records errors per completed task. Ask whether the new layout lowers the mean error count under these study conditions. This identifies the response and the direction of a treatment comparison. Assignment can support causal inference; it does not by itself make these packers representative of everyone. Do not choose a direction only after inspecting results and present it as planned.","eq":"Assigned layout → errors per task; compare means; ask whether new is lower","pic":{"t":"board","title":"Fictional packing trial: align question and design","lines":["Explanatory variable: assigned layout","Response: errors per completed task","Goal: test whether the new layout lowers the mean","Random assignment supports a causal comparison"]},"check":{"prompt":"Try it: a fictional concert hall wants a range of plausible values for the proportion of all booked tickets used this season. Which investigative goal matches? A: the status of the first sampled ticket, B: a range for the population proportion of booked tickets used this season, C: proof that every future ticket will be used. Answer A, B or C.","answer":"B","options":["A","B","C"],"hint":"Match both the population and the goal of estimating a proportion, rather than describing one ticket or proving a universal.","pic":{"t":"board","title":"Fictional concert hall: study goal","lines":["Population: all booked tickets this season","Variable: ticket used or not used","Goal: estimate a population proportion with a range"]}}},
 {skill:'inference',summary:true,say:'Start with the research question, identify the population and response, and choose a design that supports the desired conclusion. Audit sampling for bias, and experiments for comparison, control, randomization and replication; use blocks or pairs for relevant preexisting differences. Finally, interpret evidence in context: random selection and random assignment do different jobs, and statistical significance does not guarantee practical importance.',eq:'question → design → data → evidence → justified conclusion',pic:board('Collecting data: defend each link',['Define population, units and response','Choose sampling or experimental design','Check bias, confounding and randomization','Match the conclusion to the design'])}
],
progression:{requires:['math-h-spread'],operations:3,demand:'Describe reproducible randomization, diagnose study flaws, distinguish sampling and experimental designs, and justify causal and population conclusions in context.'},
items(add){
 const seen=new Set(TRY);let choice=0;
 const put=(skill,prompt,answer,pic,explanation)=>{if(seen.has(prompt))throw Error(`Repeated collecting-data prompt: ${prompt}`);seen.add(prompt);add(skill,prompt,answer,pic,explanation);};
 const mc=(skill,prompt,right,wrong,explanation,pic)=>{const c=choose(right,wrong,choice++);put(skill,`${prompt} ${c.text}. Answer A, B or C.`,c.letter,pic||evidence(prompt),explanation);};
 /* 3.1: evaluate claims and the process generating the data. */
 for(const [p,r,w,e] of [
 ['A fictional news site reports that its readers prefer electric buses after an optional homepage poll. What should be checked before claiming all residents agree?','whether the respondents represent all residents',['whether the headline uses a large font','whether every answer was stored alphabetically'],'Respondents selected themselves from site readers; their preferences may differ from those of all residents.'],
 ['Two fictional simple random samples from the same district give different estimates of support for a park. What is a valid explanation?','ordinary sampling variability',['random sampling must have failed','the district must have changed between samples'],'Different random samples can yield different statistics even when the population is unchanged.'],
 ['A fictional store doubles the size of its checkout-only survey about delivery service. Which limitation remains?','delivery-only customers are still excluded',['doubling always removes bias','the survey becomes an experiment'],'A larger sample from the same incomplete frame does not include delivery-only customers.'],
 ['A fictional walking club finds its members sleep longer than nonmembers. Which claim exceeds these observational data?','joining the club causes longer sleep',['membership and sleep are associated in these data','other differences could explain the association'],'Self-selected membership may be associated with health or schedules that also affect sleep.'],
 ['A fictional report gives a sample percentage but omits how people were selected. Which missing detail most affects population inference?','the sampling method and population covered',['the order in which names were printed','the color of the graph'],'The selection process determines whether the sample can reasonably represent the intended population.'],
 ['A fictional transit study measures wait time only when service is running smoothly. Why is its claim about typical waits questionable?','the measurement times systematically omit disruptions',['all time measurements are invalid','short waits prove every rider is satisfied'],'Sampling only smooth service systematically misses conditions with potentially longer waits.'],
 ['A fictional beverage survey asks about purchases but concludes that people prefer the cheapest flavor. What must be questioned?','whether purchases measure preference rather than price constraints',['whether purchase counts are integers','whether the flavors have names'],'The response measured must address the research question; buying a flavor need not mean preferring it.'],
 ['A fictional random sample yields an estimate above the true population value. Does this single error establish a biased method?','no; bias concerns a systematic tendency over repeated samples',['yes; any error proves bias','yes; random samples must be exact'],'Random error in one sample is not evidence of systematic overestimation by the method.'],
 ['A fictional analyst hides every survey result that contradicts a favored conclusion. What is the key problem?','selective reporting distorts the evidence',['the remaining data become a census','removing results guarantees randomization'],'Choosing results according to their conclusions can misrepresent the full evidence.'],
 ['A fictional reviewer compares an optional poll with a carefully conducted random survey of the same population. Which feature favors the random survey?','selection is governed by chance rather than willingness to respond',['its result must equal the truth exactly','its sample must contain every resident'],'Random selection reduces selection bias, although nonresponse and sampling variability still need attention.'],
 ['A fictional poll has a very large convenience sample and a tiny reported sampling error. What is the best critique?','small sampling error does not account for selection bias',['a large sample makes every method unbiased','the reported error proves causation'],'Precision calculations cannot repair a systematically unrepresentative selection process.'],
 ['A fictional water-quality team changes its instrument halfway through a study without calibration. What should be checked?','whether measurement differences reflect instruments rather than water',['whether random selection guarantees calibration','whether all instrument readings are population parameters'],'A measurement change can produce an apparent difference unrelated to actual water quality.'],
 ['A fictional island survey is carefully sampled from island residents. A report extends the result to all mainland residents. What is the problem?','the claimed population differs from the sampled population',['a random sample can never describe its own population','island residents cannot be surveyed'],'Random sampling from one population does not automatically justify inference to another.'],
 ['A fictional study headline says a tutoring method works but gives neither study design nor comparison group. Which response is justified?','request the design and comparison before accepting a causal claim',['accept cause because the headline says works','reject all data because the topic is education'],'A causal claim requires evidence from an appropriate design and a meaningful treatment comparison.']
 ])mc('truth',p,r,w,e);
 /* 3.2: distinguish target population, sample, census, observational study and imposed treatment. */
 for(const [p,r,w,e] of [
 ['A fictional library wants the mean reading time of all registered borrowers and surveys a randomly chosen subset. What is the population?','all registered borrowers',['only borrowers who answered','all books on the shelves'],'The target group is all registered borrowers; surveyed borrowers form the sample.'],
 ['A fictional airport surveys selected departing passengers to estimate satisfaction among all departing passengers. What is the sample?','the selected passengers surveyed',['all departing passengers','all airport employees'],'The sample is the subset whose responses supply the study data.'],
 ['A fictional school records the lunch choice of every enrolled student. What collection method is this?','a census of enrolled students',['a sample of only volunteers','a randomized experiment'],'Every member of the defined population is measured; no treatment is imposed.'],
 ['A fictional ecologist records existing stream temperatures and fish counts without changing conditions. What type of study is this?','an observational study',['a randomized experiment','a placebo-controlled trial'],'The ecologist observes existing conditions rather than imposing treatments.'],
 ['A fictional engineer assigns different cooling methods to motors and measures wear. What makes this an experiment?','the engineer imposes cooling treatments',['motor wear is numerical','the motors are expensive'],'Imposing treatments defines an experiment; numerical responses alone do not.'],
 ['A fictional shop alternates packaging types by day rather than randomizing them. Which description is accurate?','an experiment with nonrandom treatment assignment',['an observational study because assignment is not random','a simple random sample of days'],'Packaging is imposed, so this is an experiment; randomization is a separate design property.'],
 ['A fictional county wants opinions of all adult residents but lists only property owners for sampling. Which is the sampling frame?','the list of property owners',['all adult residents regardless of listing','only the eventual respondents'],'The frame is the list from which sampling occurs; it may miss part of the target population.'],
 ['A fictional coach compares athletes who chose their own warm-up routines. Why is the study observational?','the athletes chose routines without researcher assignment',['the coach used a stopwatch','the athletes were not given a placebo'],'Researchers did not impose the routines, so other differences may explain performance.'],
 ['A fictional survey randomly selects commuters but does not assign their routes. What does random selection support?','generalization to the commuter population sampled',['proof that routes cause stress','guaranteed absence of response error'],'Selection supports population inference when the survey is well conducted; it does not impose routes.'],
 ['A fictional laboratory randomly assigns volunteer typists to keyboards. What does the random assignment primarily support?','a causal comparison of keyboards for these typists',['automatic generalization to every worker','a census of typists'],'Assignment balances other characteristics in expectation, supporting causal comparison under controlled conditions.'],
 ['A fictional census attempts to contact every tenant, but some refuse. Which statement is correct?','the census attempt can still have nonresponse bias',['calling it a census removes nonresponse','refusal turns the study into an experiment'],'Attempting to measure everyone does not guarantee that missing responses are harmless.'],
 ['A fictional researcher wants to compare the effects of two music conditions on concentration. Which plan directly imposes the explanatory variable?','assign participants to music conditions and measure concentration',['ask participants which music they already chose','record music preferences without changing them'],'Assigning music conditions imposes a treatment and creates an experiment.'],
 ['A fictional biologist wants to estimate tree disease prevalence without altering trees. Which plan fits that goal?','randomly sample trees and record disease status',['randomly infect trees and call the result natural prevalence','survey only obviously diseased trees'],'A probability sample with observation estimates prevalence; altering disease or selecting by outcome changes the question.'],
 ['A fictional researcher assigns classroom teaching methods but surveys individual pupils. What identifies the study as experimental?','the researcher assigned the teaching methods',['the number of pupils surveyed','the existence of a questionnaire'],'An experiment is defined by imposed treatments, even when a survey records the response.']
 ])mc('planning',p,r,w,e);
 /* 3.3: designs and reproducible selection instructions, including digit streams. */
 for(const [p,r,w,e] of [
 ['A fictional factory draws equally likely subsets of workers of a fixed size from its complete roster. Which sampling design is used?','simple random sampling',['convenience sampling','cluster sampling'],'Every possible subset of the specified size has the same chance, which defines an SRS.'],
 ['A fictional college randomly samples students from each academic division. Which sampling design is used?','stratified random sampling',['cluster sampling','voluntary response sampling'],'Every division contributes a random sample; divisions serve as strata.'],
 ['A fictional utility randomly selects city blocks and inspects every meter on those blocks. Which sampling design is used?','cluster sampling',['stratified random sampling','simple random sampling of individual meters'],'Whole selected blocks are measured, so blocks are clusters.'],
 ['A fictional bottling line uses a random start and then inspects every twentieth bottle. Which sampling design is used?','systematic random sampling',['voluntary response sampling','a census'],'A random start followed by a fixed interval defines systematic random sampling.'],
 ['A fictional survey must include every age band, and opinions differ by age. Which plan is most appropriate?','randomly sample within each age band',['randomly choose one age band and survey only it','survey whoever arrives first'],'Stratifying on a characteristic related to the response ensures each band is represented and can improve precision.'],
 ['A fictional field team faces high travel costs between villages. Which plan uses one-stage cluster sampling?','randomly choose villages and survey every household there',['sample a few households in every village','choose the nearest households without chance'],'A one-stage cluster design selects whole groups, often saving travel cost.'],
 ['A fictional list repeats day and night shifts in order, and a sampling interval matches that cycle. What is the main concern?','systematic sampling may repeatedly select only one shift',['systematic sampling always includes every shift','a random start eliminates every periodicity problem'],'A matching interval can select a single type repeatedly even with a random start.'],
 ['A fictional class chooses either the entire front row or the entire back row by coin toss. Each pupil has equal inclusion chance. Why is this not necessarily an SRS of pupils?','many subsets of that size can never be selected',['an SRS requires unequal inclusion chances','coins cannot be used for random selection'],'Equal individual probabilities are insufficient; an SRS requires equal chances for all fixed-size subsets.'],
 ['A fictional roster has distinct labels. Which generator procedure yields an SRS without replacement?','uniformly choose unused labels until the required count is reached',['keep duplicate labels as additional people','choose the labels that look most varied'],'Uniform selection from remaining individuals gives every fixed-size subset equal probability.'],
 ['A fictional analyst converts two-digit random groups to roster labels by assigning every out-of-range value to the first person. Why is that flawed?','the first person receives extra selection probability',['it gives every subset equal probability','out-of-range values can never occur'],'Mapping all invalid groups to one person favors that label; skip them instead.'],
 ['A fictional wildlife study divides a region into habitats and samples sites randomly in every habitat. Why can this improve precision?','habitats can group sites with similar responses',['stratification guarantees identical responses','sampling every habitat removes all measurement error'],'Strata related to the response can reduce variation among sample estimates compared with an SRS of the same size.'],
 ['A fictional assessor randomly selects schools, then randomly samples pupils within selected schools. Which description fits?','a multistage sample',['a one-stage cluster sample measuring every pupil','a census of all schools'],'There is random selection at two stages: schools and then pupils, rather than all pupils in selected schools.']
 ])mc('sampling',p,r,w,e);
 for(const [N,a,b,c] of [[36,7,18,25],[58,11,23,46],[73,15,32,67],[82,21,45,70]]){const stream=[99,a,a,0,b,c],prompt=`A fictional roster labels people 01 through ${N}. Read two-digit groups ${stream.map(v=>String(v).padStart(2,'0')).join(', ')} from left to right, skipping repeats and out-of-range labels. What is the third selected label?`;put('sampling',prompt,c,evidence(prompt),`99 and 00 are outside 01 through ${N}, and the repeated ${a} is skipped. The distinct valid labels are ${a}, ${b}, ${c}; the third is ${c}.`);}
 for(const [N,k,r] of [[120,12,5],[154,14,8],[176,16,7],[210,15,6]]){const prompt=`A fictional systematic sample uses a roster of ${N} people, interval ${k}, and random start ${r}. Selecting ${r} and then every ${k}th position until the roster ends, how many people are sampled?`;put('sampling',prompt,N/k,evidence(prompt),`The selected positions are ${r}, ${r+k}, …, ${r+N-k}. There are ${N/k} positions, since the roster length is ${N/k} complete intervals.`);}
 /* 3.4: diagnose mechanism and direction, and choose a repair that addresses it. */
 for(const [p,r,w,e] of [
 ['A fictional city samples residents from a smartphone-app list, excluding residents without smartphones. Which problem is directly described?','undercoverage',['nonresponse among selected people','random assignment'],'Part of the target population has no opportunity to be selected from this frame.'],
 ['A fictional random mail survey selects households, but many selected households never reply. Which problem is directly described?','nonresponse',['undercoverage because they were never selected','randomized blocking'],'The missing data come from households that were selected, distinguishing nonresponse from frame omissions.'],
 ['A fictional teacher asks pupils face to face whether they ever copy homework. Pupils hide copying to avoid embarrassment. Which problem is directly described?','response bias',['cluster sampling','sampling variability alone'],'The answers may be systematically inaccurate because the interview setting encourages socially desirable responses.'],
 ['A fictional newspaper invites anyone who wishes to submit an opinion about stadium funding. Which sampling problem is central?','voluntary response',['simple random sampling','a randomized experiment'],'People decide for themselves whether to respond; those with strong opinions may be overrepresented.'],
 ['A fictional researcher surveys only friends who happen to be nearby. Which sampling method is used?','convenience sampling',['stratified random sampling','systematic random sampling'],'Availability, not chance selection from the population, determines inclusion.'],
 ['A fictional town estimates internet access using only an online form. Residents without access cannot respond. In which direction is estimated access likely biased?','upward',['downward','guaranteed to be exactly correct'],'People without internet access are excluded, so the proportion with access is likely overestimated.'],
 ['A fictional company asks employees about satisfaction while their supervisor watches. If unhappy employees fear retaliation, how is reported satisfaction likely biased?','upward',['downward','unchanged with certainty'],'Fear of retaliation can suppress negative reports, inflating measured satisfaction.'],
 ['A fictional survey of commuting time omits remote rural residents known to have longer commutes. How is the mean commute likely biased?','downward',['upward','guaranteed to be unbiased'],'Leaving out a group with longer commutes tends to reduce the estimated mean.'],
 ['A fictional survey has low response, but nothing is known about nonrespondents. What can be said about the direction of bias?','it cannot be determined from the information given',['it must be upward','it must be downward'],'Nonresponse raises concern, but direction requires knowing how nonrespondents differ on the response.'],
 ['A fictional questionnaire asks whether a wasteful new tax should be stopped. Which revision directly reduces leading-wording bias?','ask neutrally whether respondents support or oppose the tax',['keep wasteful and enlarge the font','survey more people using the same wording'],'Neutral wording avoids pushing respondents toward a preferred answer.'],
 ['A fictional survey loses many selected shift workers because calls occur only at noon. Which change best addresses this nonresponse?','make follow-up contacts at varied times',['replace every missing worker with a nearby friend','delete shift workers from the target population'],'Varying contact times gives selected workers more opportunities to respond without replacing them nonrandomly.'],
 ['A fictional town uses an outdated housing list that omits new apartments. Which change directly repairs the frame?','update the list to include new apartments before random sampling',['randomly select more old addresses only','use a larger sample of the same omissions'],'Updating coverage addresses the source of exclusion; simply sampling more from the old list does not.'],
 ['A fictional phone poll reaches a random sample, but the interviewer changes answers to favor a candidate. What remains despite random selection?','response or recording bias',['guaranteed unbiased measurement','a randomized treatment effect'],'Random selection cannot protect against altered or incorrectly recorded responses.'],
 ['A fictional station receives mostly angry callers after inviting feedback. Why might the results overstate dissatisfaction?','dissatisfied listeners may be more motivated to volunteer',['every listener had to respond','anger proves random sampling'],'Voluntary response can overrepresent people with strong feelings, here plausibly those who are dissatisfied.'],
 ['A fictional health survey asks about spending over a long past period, and respondents systematically forget purchases. What is the concern?','response bias from inaccurate recall',['random assignment of purchases','a guaranteed census'],'Systematic recall errors affect the answers provided, a form of response bias.'],
 ['A fictional analyst replaces nonrespondents in a random survey with readily available neighbors. What is the concern?','the replacements introduce convenience selection',['the replacements preserve an SRS automatically','the study gains random treatment assignment'],'Easy-to-reach substitutes may differ from the selected people and are not selected by the original random procedure.']
 ])mc('bias',p,r,w,e);
 /* 3.5: experimental units, factorial treatments, controls and alternative explanations. */
 for(const [p,r,w,e] of [
 ['A fictional bakery assigns oven temperatures independently to whole batches and measures loaf volume. What are the experimental units?','the batches',['the temperature settings','the measured volumes'],'The batch is the smallest unit independently assigned a treatment; loaves within a batch share it.'],
 ['A fictional lens trial assigns coating type and measures glare. What is the response variable?','measured glare',['coating type','the randomization procedure'],'Glare is the measured outcome that may respond to coating type.'],
 ['A fictional printing trial varies ink brand and paper texture. What are the factors?','ink brand and paper texture',['the sheets and the printers','only the observed drying time'],'Factors are explanatory variables deliberately varied by the experimenter.'],
 ['A fictional engine trial sets fuel grade to regular or premium. What are regular and premium?','levels of the fuel-grade factor',['experimental units','response variables'],'Levels are the specific settings of a factor.'],
 ['A fictional fabric trial varies dye type and drying temperature. What is one treatment?','a particular dye type combined with a particular temperature',['all fabrics in the population','only the final color measurement'],'A treatment is a combination of the factor levels applied to a unit.'],
 ['A fictional experiment applies a fertilizer to one tray and counts many seedlings in that tray. Why do the seedlings not provide independent treatment replication?','the tray received the single treatment assignment',['measuring more seedlings always means more independent assignments','replication means copying the same number'],'Independent replication requires multiple independently assigned experimental units, not repeated measurements within one unit.'],
 ['A fictional detergent trial compares cleaned fabric only with its own appearance before cleaning. Why add a concurrent comparison treatment?','to distinguish the detergent effect from changes that occur anyway',['to guarantee the new detergent wins','to remove the need for random assignment'],'A comparison group helps assess what happens without the new treatment under otherwise similar conditions.'],
 ['A fictional insulation trial randomly assigns panels to materials. What is the main purpose of this randomization?','balance other variables across treatments in expectation',['force every response to be equal','guarantee each group is identical in every trait'],'Chance assignment reduces systematic differences in other variables; exact balance is not guaranteed.'],
 ['A fictional plant-light trial uses the same watering schedule for all treatments. Which design principle does this illustrate?','control of other conditions',['voluntary response','random sampling from a population'],'Holding water constant helps isolate the effect of the light treatment.'],
 ['A fictional wound-gel trial gives some subjects an inactive gel that looks and feels the same. What is the inactive gel?','a placebo',['a sampling frame','a response variable'],'A placebo resembles the active treatment while omitting its active ingredient, controlling expectations.'],
 ['A fictional taste trial hides drink identity from participants. What potential bias is this intended to reduce?','expectations influencing reported taste',['undercoverage in a city census','the need to measure a response'],'Blinding subjects limits changes in their reports caused by knowing treatment identity.'],
 ['A fictional therapy trial hides assignments from subjects and from staff interacting with and evaluating them. What is this procedure?','double-blinding',['matched-pairs sampling','a census'],'Both subjects and relevant study personnel are unaware of assignments, reducing expectation and evaluation bias.'],
 ['A fictional reading experiment uses the new method only with an experienced tutor and the old method only with a novice. Why is tutor experience confounded?','its effect cannot be separated from the method effect',['tutor experience was held constant','the method was never imposed'],'Method and tutor experience vary together, so their effects cannot be isolated.'],
 ['A fictional experiment uses several independently assigned devices for each battery treatment. Which principle does this illustrate?','replication',['undercoverage','voluntary response'],'Multiple independent units per treatment reveal natural variability and improve treatment comparisons.']
 ])mc('experiment',p,r,w,e);
 for(const [a,b,n] of [[3,4,5],[4,2,7],[5,3,4],[4,4,3]]){const prompt=`A fictional full factorial coating experiment uses ${a} resin levels and ${b} curing levels, with ${n} independently assigned panels per treatment. How many distinct treatments are there?`;put('experiment',prompt,a*b,evidence(prompt),`Each resin level is combined with each curing level, so there are ${a} × ${b} = ${a*b} treatments. The ${n} panels per treatment provide replication, not additional treatment types.`);}
 /* 3.6: choose and implement a design; compare at the level of randomization. */
 for(const [p,r,w,e] of [
 ['A fictional tile trial randomly divides all available tiles into adhesive groups without making blocks. Which design is used?','completely randomized design',['randomized block design','matched pairs'],'All tiles are randomized together, with no preexisting grouping used in assignment.'],
 ['A fictional study groups patients by initial severity, then randomly assigns therapies within every severity group. Which design is used?','randomized block design',['cluster sampling','completely randomized with no blocks'],'Severity defines blocks; treatment assignment is randomized separately inside each block.'],
 ['A fictional exercise trial pairs participants of similar fitness, then randomly assigns one in each pair to each program. Which design is used?','matched pairs',['a census','cluster sampling'],'Pairs of similar participants form blocks of size two, with random assignment within each pair.'],
 ['A fictional hearing trial gives every listener both headphones in random order. Which design is used?','matched pairs',['independent groups with no pairing','cluster sampling'],'Each listener serves as their own comparison, so responses are paired within listeners.'],
 ['A fictional paper-strength experiment knows humidity strongly affects strength. Which blocking variable is most useful?','humidity before treatment',['the measured strength after treatment','a random label unrelated to strength'],'Blocks should use a pre-treatment characteristic related to the response, reducing unexplained variation.'],
 ['A fictional grower blocks saplings by initial height, then assigns every tall sapling to feed X and every short sapling to feed Y. What is wrong?','height is confounded with feed because treatments are not randomized within blocks',['this is a valid randomized block design','height has been held constant across treatments'],'Each block must contain a randomized comparison; otherwise height and feed effects are mixed.'],
 ['A fictional researcher blocks machines by model. What must happen next for a randomized block experiment?','randomly assign each treatment within every model block',['assign one treatment to each entire model block','ask operators to choose treatments'],'Randomization occurs within each block, allowing treatment comparisons among similar machines.'],
 ['A fictional crossover trial always tests screen A before screen B. If users improve with practice, what change addresses this problem?','randomize screen order across users',['keep the order and call it blinded','analyze only the second response'],'Randomized order helps distribute practice and fatigue effects across treatments.'],
 ['A fictional caffeine crossover study has lingering treatment effects between sessions. Which design feature addresses carryover?','allow an appropriate washout period before the next treatment',['apply both treatments simultaneously','omit randomization of order'],'A washout period allows prior effects to dissipate; random order alone need not remove carryover.'],
 ['A fictional fertilizer experiment blocks by soil type. Why compare fertilizer responses within soil types?','to account for soil-related variation in yield',['to estimate only the effect of soil type','to make every plot receive the same fertilizer'],'Within-block comparisons reduce variation due to soil while retaining the fertilizer contrast.'],
 ['A fictional analyst collects observations, then groups units by their measured outcomes and calls them experimental blocks. What is the flaw?','blocks should be defined before assignment using relevant characteristics',['post-outcome grouping is random assignment','blocks are always based on final outcomes'],'Blocking is a design choice before treatment assignment, not a grouping created from the observed response.'],
 ['A fictional seed experiment uses blocks, while a separate survey uses strata. What is the key distinction?','blocks organize treatment assignment; strata organize sample selection',['both are names for voluntary response','strata require imposing treatments'],'Both group similar individuals, but experimental blocks and sampling strata serve different tasks.'],
 ['A fictional memory experiment has each participant use both study methods. Which quantity should be compared across participants?','each participant’s difference between the two method scores',['all scores as if from unrelated people','only the larger score from each participant'],'A paired analysis preserves the within-person comparison and accounts for person-to-person differences.'],
 ['A fictional researcher needs an equal-sized random allocation of numbered tablets to two interfaces. Which procedure works?','uniformly shuffle all tablet labels and assign the first half to one interface',['sort by current speed and assign the fastest half to one interface','let users select their preferred interface'],'A uniform shuffle makes all equal-sized allocations equally likely and avoids systematic speed or preference differences.'],
 ['A fictional study divides a complete roster by region and randomly selects households in each region without treatments. Which label fits?','stratified sampling rather than experimental blocking',['a randomized block experiment','a placebo experiment'],'The random action selects observational units; no treatments are assigned.'],
 ['A fictional trial forms pairs of shoes from the same production batch and randomizes finishes within pairs. Why pair by batch?','to reduce variation due to production differences',['to guarantee a significant finish effect','to replace random assignment with matching'],'Pairing related units helps account for batch variation; randomization and evidence are still needed.']
 ])mc('design',p,r,w,e);
 /* 3.7: all four inference scopes, significant versus important, and a linked exam-style investigation. */
 for(const [p,r,w,e] of [
 ['A fictional trial randomly samples eligible residents, randomly assigns exercise programs, and finds a significant difference. Assuming a well-conducted trial, which conclusion is supported?','a causal effect for the eligible-resident population',['association only with no possible causal evidence','a causal effect for every person on Earth'],'Random selection supports the defined population; random assignment and significant evidence support cause in that population.'],
 ['A fictional survey randomly samples workers and records their chosen lunch habits and energy. Which conclusion is supported?','an association generalizable to the sampled worker population',['lunch habits are proven to cause energy changes','the result applies only to volunteers despite random selection'],'The random sample supports population association, but self-chosen habits are not randomly assigned.'],
 ['A fictional trial recruits volunteer cyclists and randomly assigns helmets, finding a significant comfort difference. Which scope is justified?','causal evidence for the study cyclists; broad population generalization is limited',['causal evidence for all cyclists automatically','no causal evidence is possible because cyclists volunteered'],'Volunteer recruitment limits generalization; it does not undo the causal value of random assignment within the trial.'],
 ['A fictional analyst surveys nearby friends about their self-chosen diets and moods. What is justified by design alone?','describe association among these friends only',['infer diet causes mood throughout the city','generalize to the city because diets were measured'],'Neither probability sampling nor random treatment assignment is present.'],
 ['A fictional randomized trial produces a statistically significant treatment difference. What does significant mean here?','a result at least as extreme is unlikely under a no-effect chance model',['the treatment must have a large useful effect','there is no possibility of sampling or assignment variation'],'Significance concerns incompatibility with a no-effect model, not certainty or size of benefit.'],
 ['A fictional randomized trial detects a tiny but statistically significant increase in battery life. What additional issue matters for adoption?','whether the improvement is practically worthwhile',['whether significance guarantees a large benefit','whether a small effect is mathematically impossible'],'Practical importance depends on effect size, costs and context, not just statistical significance.'],
 ['A fictional trial finds no statistically significant difference between training methods. Which conclusion is appropriate?','the study has insufficient evidence of a difference',['the methods have been proven identical','the no-effect hypothesis has probability one'],'Failure to find convincing evidence does not establish equality of treatments.'],
 ['A fictional analyst reports a small probability of an extreme result assuming no treatment effect. Which interpretation is incorrect?','the probability that no treatment effect is true',['a conditional probability under the no-effect model','evidence against no effect when the probability is sufficiently small'],'The chance calculation assumes no effect; it does not assign a probability to that assumption itself.'],
 ['A fictional experiment assigns treatments by age group without randomization and finds a large difference. Why is a causal conclusion weak?','age differences may explain the response difference',['large differences always prove cause','a numerical response eliminates confounding'],'A large observed difference cannot repair confounded treatment assignment.'],
 ['A fictional randomized trial uses only one neighborhood’s volunteers. Which claim exceeds its design?','the estimated effect automatically applies to the entire nation',['assignment supports a treatment comparison within the trial','the volunteer population may differ from the nation'],'Random assignment does not turn a local volunteer group into a random national sample.'],
 ['A fictional well-conducted random survey finds a statistically significant association between screen time and stress. Why is cause still unproven?','screen time was not randomly assigned and other variables may explain the association',['significance converts observation into an experiment','a random sample is identical to random treatment assignment'],'Significance of association does not replace an experimental design for causal inference.'],
 ['A fictional completely randomized trial compares treatment means. Under a no-effect randomization model, what is shuffled?','treatment labels while keeping the observed responses fixed',['responses are changed to make treatments equal','only unusually large responses are discarded'],'Under the no-effect model, outcomes would not change with assignment, so labels can be reassigned to model chance variation.'],
 ['A fictional blocked experiment is assessed by randomization simulation. How should labels be shuffled?','within the original blocks following the assignment design',['freely across blocks that never shared assignments','only between the largest responses'],'The simulation must mirror the actual assignment scheme, preserving restrictions such as blocks.'],
 ['A fictional random sample of bus riders receives randomly assigned app versions, but many users of one version drop out. What qualification is needed?','differential dropout may bias the treatment comparison',['initial randomization guarantees an unbiased final comparison','dropout guarantees no effect'],'Losing units differently across treatment groups can undermine comparability even after valid initial assignment.']
 ])mc('inference',p,r,w,e);
 for(const [extreme,total] of [[17,500],[23,1000],[31,1250],[43,2000]]){const answer=extreme/total,prompt=`A fictional no-effect randomization simulation gives ${extreme} results at least as extreme as the observed difference out of ${total} shuffles. What is the estimated chance probability? Give a decimal to four places.`;put('inference',prompt,answer,evidence(prompt),`Use the fraction at least as extreme: ${extreme}/${total} = ${answer.toFixed(4)}. This is a probability conditional on the no-effect model, not the probability that the model is true.`);}
 const study='In a fictional transit trial, 84 volunteer drivers are randomly assigned equally to two dashboard layouts. All complete the trial under the same conditions; the response is the number of navigation errors.';
 mc('experiment',`${study} Part (a): what is the experimental unit?`,'one driver',['one navigation error','one dashboard layout'],'A driver receives an independent layout assignment; errors are the response.');
 put('design',`${study} Part (b): how many drivers receive each layout?`,42,board('Fictional transit trial',['84 volunteer drivers','Two equally sized assignment groups']),`Equal allocation divides 84 drivers into two groups of 42.`);
 mc('inference',`${study} Part (c): a statistically significant difference is found. Which conclusion is justified?`,'layout caused a difference for these study drivers under these conditions',['layout caused the same difference for all drivers worldwide','volunteering makes causal evidence impossible'],'Random assignment supports cause in the study; volunteer recruitment limits population generalization.');

 /* Fall 2026 topics 1.1 and 1.10: original investigative-question scenarios. */
 for(const [p,r,w,e] of [
 [
  "A fictional parcel company wants a plausible range for the mean delay, in minutes, of all deliveries completed this week. Which question fits?",
  "What range is plausible for the population mean delay this week?",
  [
   "What was the delay of the first sampled parcel?",
   "Is every delivery in every future year guaranteed to be on time?"
  ],
  "The stated population is this week’s completed deliveries and the target is their mean delay. Estimating a range differs from reporting one observation or proving a universal."
 ],
 [
  "A fictional dental practice asks whether the proportion of all scheduled patients missing an appointment this month is below 0.1. Which alternative matches the planned question?",
  "p < 0.1 for that population",
  [
   "p > 0.1 for that population",
   "the mean patient age exceeds 0.1 years"
  ],
  "The outcome is binary and the parameter is a population proportion. Below specifies a less-than alternative, fixed before examining results."
 ],
 [
  "A fictional bus depot wants to estimate the mean charging time of all buses charged there in September. Which data directly address that variable?",
  "charging times in minutes for a suitable sample of those buses",
  [
   "only the buses’ paint colors",
   "only the mechanics’ ages"
  ],
  "Charging duration is the quantitative response. Paint color and employee age do not directly measure the requested time."
 ],
 [
  "A fictional district asks what proportion of all its households have a working smoke alarm. Which population is named by the question?",
  "all households in that district",
  [
   "only the first household contacted",
   "all households in every country"
  ],
  "The target group is all district households. A selected household is part of a sample, while a worldwide claim exceeds the stated population."
 ],
 [
  "A fictional battery study asks whether the population mean lifetime differs from 12 hours. Which feature of the question guides the test direction?",
  "differs specifies a two-sided alternative",
  [
   "12 forces a greater-than alternative",
   "hours forces a less-than alternative"
  ],
  "Differs allows either direction of departure. The units and numerical reference value do not themselves determine the direction."
 ],
 [
  "A fictional reservoir team wants a confidence interval for the proportion of water samples meeting a purity standard. What is the analysis goal?",
  "estimate a population proportion with a range",
  [
   "prove every sample everywhere meets the standard",
   "report only whether the first observation meets the standard"
  ],
  "A confidence interval expresses estimation uncertainty for a population parameter. One observation and a universal guarantee are different goals."
 ],
 [
  "A fictional survey records employment category and preferred transport mode for a random sample of local adults. Which investigative question fits these two categorical variables?",
  "Are employment category and preferred transport mode associated among local adults?",
  [
   "What is the mean of transport-mode names?",
   "Does transport mode necessarily cause every employment decision?"
  ],
  "Association compares categorical distributions in the target population. Arbitrary category names have no numerical mean, and observation alone does not establish cause."
 ],
 [
  "A fictional trial randomly assigns volunteer proofreaders to two screen colors and measures missed errors. Which question matches the strongest design-supported type of conclusion?",
  "Does assigned screen color affect mean missed errors for these participants under the trial conditions?",
  [
   "Does screen color have exactly the same effect on everyone worldwide?",
   "What proves the volunteers were a random sample of all readers?"
  ],
  "Random assignment supports a causal comparison under study conditions. Volunteering does not provide random population sampling or establish identical effects for all people."
 ],
 [
  "A fictional analyst observes an increase, then rewrites a planned decrease-only question as increase-only while claiming the direction was chosen before data collection. What is the problem?",
  "the reported plan misrepresents a choice made after seeing results",
  [
   "data always forbid any exploratory follow-up question",
   "the sample automatically becomes a census"
  ],
  "Exploratory follow-up is possible, but an outcome-dependent choice must not be represented as prespecified. Honest reporting separates planned and exploratory analyses."
 ],
 [
  "A fictional robotics team proposes to estimate the average repair time but records no start or finish times. What should be fixed in its plan?",
  "collect measurements from which repair duration can be determined",
  [
   "change the goal to match whichever result looks impressive",
   "assume missing times are all zero"
  ],
  "A feasible investigation needs data addressing its variable. Changing goals opportunistically or inventing zero measurements does not provide repair durations."
 ],
 [
  "A fictional factory asks whether a new method produces fewer defective parts than the current method. Before gathering data, what would make the question more precise?",
  "define the target production population and compare the two defect proportions",
  [
   "choose the alternative only after seeing which method wins",
   "replace defect status with employees’ favorite colors"
  ],
  "A comparison of defect proportions aligns the binary response with the method groups. Specifying the target population sets the scope; choosing direction afterward changes the planned question."
 ],
 [
  "A fictional analyst wants to estimate customer satisfaction but writes only Is service good? What clarification would make the investigation measurable?",
  "define the customer population and how satisfaction will be recorded",
  [
   "assume every customer has the same opinion",
   "promise that a sample will remove all uncertainty"
  ],
  "Operational definitions specify what will be measured and from whom. Customer variation and sampling uncertainty remain possible after a question is clarified."
 ]
])mc('investigative',p,r,w,e);
}};
